public import CoreGraphics
public import Foundation

/// What each icon means and its SF Symbol fallback
/// (Resources/icon-catalog.json, generated by scripts/icons/build_pack.py).
public nonisolated struct IconCatalog: Sendable, Decodable {
    public let entries: [IconCatalogEntry]
    private let index: [IconName: IconCatalogEntry]

    public init(entries: [IconCatalogEntry]) {
        self.entries = entries
        index = Dictionary(entries.map { ($0.name, $0) }, uniquingKeysWith: { first, _ in first })
    }

    public init(data: Data) throws {
        self = try JSONDecoder().decode(IconCatalog.self, from: data)
    }

    private enum CodingKeys: String, CodingKey {
        case icons
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.init(entries: try container.decode([IconCatalogEntry].self, forKey: .icons))
    }

    /// The catalog shipped in this module's bundle, loaded once; empty when
    /// the bundle is missing or unreadable.
    public static let bundled: IconCatalog = {
        guard let data = IconResources.json(named: "icon-catalog") else {
            return IconCatalog(entries: [])
        }
        do {
            return try IconCatalog(data: data)
        } catch {
            IconResources.logger.error("icon-catalog.json did not decode: \(String(describing: error), privacy: .public)")
            return IconCatalog(entries: [])
        }
    }()

    public func entry(for name: IconName) -> IconCatalogEntry? {
        index[name]
    }

    /// The style `name` draws in at `size`: its dense style below
    /// `CGFloat.iconDenseThreshold`, else `requested`.
    public func style(_ requested: IconStyle, for name: IconName, size: CGFloat) -> IconStyle {
        if size < CGFloat.iconDenseThreshold, let dense = entry(for: name)?.denseStyle {
            return dense
        }
        return requested
    }
}
